globalTheme.globalCss:
html { -webkit-text-size-adjust: 100%; }
body { overflow-x: hidden; background-color: #ffffff; font-family: var(--family-body); font-size: 15px; line-height: 1.625; color: var(--color-navy-900); -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }
h1, h2, h3, h4, h5, h6, [class*='--family-title'] { font-family: var(--family-title); }
::selection { background: #dc3a1f; color: #fff; }
:focus-visible { outline: 2px solid #dc3a1f; outline-offset: 2px; }
img { -webkit-user-drag: none; }
@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
@keyframes plane-fly { 0%, 100% { transform: translate(0, 0) rotate(0deg); } 50% { transform: translate(8px, -6px) rotate(3deg); } }
@keyframes ring-pulse { 0% { box-shadow: 0 0 0 0 rgba(220,58,31,0.45); } 70% { box-shadow: 0 0 0 16px rgba(220,58,31,0); } 100% { box-shadow: 0 0 0 0 rgba(220,58,31,0); } }
@keyframes shimmer { 100% { transform: translateX(100%); } }
